use serde::Serialize;
use std::sync::OnceLock;

/// Embedded GeoNames subset: latitude, longitude, name, name_zh, country,
/// population. Generated by `tools/build_gazetteer.py`.
const CITIES_TSV: &str = include_str!("../../../assets/cities.tsv");

/// Beyond this distance the nearest city says more about the map than the
/// footage, so `{location}` stays empty.
pub const MAX_DISTANCE_KM: f64 = 150.0;

#[derive(Debug, Clone, Serialize, PartialEq)]
pub struct Place {
    pub name: String,
    pub name_zh: Option<String>,
    pub country: String,
    pub distance_km: f64,
}

struct City {
    lat: f64,
    lon: f64,
    name: String,
    name_zh: Option<String>,
    country: String,
    population: u64,
}

fn cities() -> &'static [City] {
    static CITIES: OnceLock<Vec<City>> = OnceLock::new();
    CITIES.get_or_init(|| {
        CITIES_TSV
            .lines()
            .filter_map(|line| {
                let mut fields = line.split('\t');
                let lat = fields.next()?.parse().ok()?;
                let lon = fields.next()?.parse().ok()?;
                let name = fields.next()?.to_string();
                let zh = fields.next().unwrap_or_default();
                let country = fields.next()?.to_string();
                let population = fields.next().and_then(|v| v.parse().ok()).unwrap_or(0);
                Some(City {
                    lat,
                    lon,
                    name,
                    name_zh: (!zh.is_empty()).then(|| zh.to_string()),
                    country,
                    population,
                })
            })
            .collect()
    })
}

/// Nearest meaningful city within [`MAX_DISTANCE_KM`].
///
/// The nearest point is often a district or suburb (Shanghai's Huangpu sits
/// closer than Shanghai's centre). Candidates within 40 km of the nearest
/// point compete on `sqrt(population) / (distance + 10)`, which keeps a
/// metropolis from being beaten by its own district while still preferring a
/// genuinely close town over a far-away giant.
pub fn lookup(lat: f64, lon: f64) -> Option<Place> {
    if !lat.is_finite() || !lon.is_finite() || !(-90.0..=90.0).contains(&lat) {
        return None;
    }
    let lat_span = MAX_DISTANCE_KM / 111.0;
    let mut candidates: Vec<(&City, f64)> = Vec::new();
    for city in cities() {
        if (city.lat - lat).abs() > lat_span {
            continue;
        }
        let distance = haversine_km(lat, lon, city.lat, city.lon);
        if distance <= MAX_DISTANCE_KM {
            candidates.push((city, distance));
        }
    }
    let nearest = candidates
        .iter()
        .map(|(_, distance)| *distance)
        .fold(f64::INFINITY, f64::min);
    if !nearest.is_finite() {
        return None;
    }
    let window = nearest + 40.0;
    candidates
        .into_iter()
        .filter(|(_, distance)| *distance <= window)
        .max_by(|(left_city, left_distance), (right_city, right_distance)| {
            let left = score(left_city, *left_distance);
            let right = score(right_city, *right_distance);
            left.partial_cmp(&right)
                .unwrap_or(std::cmp::Ordering::Equal)
        })
        .map(|(city, distance)| Place {
            name: city.name.clone(),
            name_zh: city.name_zh.clone(),
            country: city.country.clone(),
            distance_km: (distance * 10.0).round() / 10.0,
        })
}

fn score(city: &City, distance_km: f64) -> f64 {
    (city.population as f64).sqrt() / (distance_km + 10.0)
}

fn haversine_km(lat1: f64, lon1: f64, lat2: f64, lon2: f64) -> f64 {
    const EARTH_RADIUS_KM: f64 = 6371.0088;
    let dlat = (lat2 - lat1).to_radians();
    let dlon = (lon2 - lon1).to_radians();
    let a = (dlat / 2.0).sin().powi(2)
        + lat1.to_radians().cos() * lat2.to_radians().cos() * (dlon / 2.0).sin().powi(2);
    2.0 * EARTH_RADIUS_KM * a.sqrt().asin()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn finds_hangzhou() {
        let place = lookup(30.2741, 120.1551).expect("hangzhou");
        assert_eq!(place.name, "Hangzhou");
        assert_eq!(place.name_zh.as_deref(), Some("杭州"));
        assert_eq!(place.country, "CN");
        assert!(place.distance_km < 5.0);
    }

    #[test]
    fn prefers_the_metropolis_over_its_district() {
        // Shanghai city centre; Huangpu district is closer but should not win.
        let place = lookup(31.2304, 121.4737).expect("shanghai");
        assert_eq!(place.name, "Shanghai");
        assert_eq!(place.name_zh.as_deref(), Some("上海"));
    }

    #[test]
    fn finds_gopro_typical_location() {
        // Somewhere in San Francisco.
        let place = lookup(37.7749, -122.4194).expect("san francisco");
        assert_eq!(place.country, "US");
        assert!(!place.name.is_empty());
    }

    #[test]
    fn returns_none_in_the_open_ocean() {
        assert!(lookup(0.0, -140.0).is_none());
        assert!(lookup(f64::NAN, 0.0).is_none());
    }
}
